cat > /tmp/bot-test/test.mjs <<'EOF'
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { mkdtemp, utimes, mkdir, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g4-3/bot.mjs';
const exec = promisify(execFile);
const base = await mkdtemp(join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = join(base, 'nested', 'state'); // does not exist yet
const { reserve, release } = await import(BOT);

const H = 3600e3, M = 60e3;
const t0 = new Date('2026-10-22T09:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);
const req = (o = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0, ...o });
let passed = 0;
const test = async (name, fn) => { await fn(); passed++; console.log('ok -', name); };

await test('creates missing STATE_DIR and allows first send', async () => {
  const r = await reserve(req(), t0);
  assert.equal(r.allowed, true); assert.equal(r.reason, null); assert.match(r.reservationId, /^[0-9a-f]{64}\.[0-9a-f-]{36}$/);
});

await test('maxPerWindow caps sends in a rolling window', async () => {
  const u = { userId: 'cap' };
  assert.equal((await reserve(req({ ...u }), at(0))).allowed, true);
  assert.equal((await reserve(req({ ...u }), at(1 * M))).allowed, true);
  assert.equal((await reserve(req({ ...u }), at(2 * M))).allowed, true);
  const d = await reserve(req({ ...u }), at(3 * M));
  assert.deepEqual([d.allowed, d.reason, d.reservationId], [false, 'max_per_window_reached', null]);
});

await test('window rolls: old send drops out after windowHours', async () => {
  const u = { userId: 'roll' }; const o = { maxPerWindow: 2, windowHours: 1 };
  assert.equal((await reserve(req({ ...u, ...o }), at(0))).allowed, true);
  assert.equal((await reserve(req({ ...u, ...o }), at(10 * M))).allowed, true);
  assert.equal((await reserve(req({ ...u, ...o }), at(20 * M))).reason, 'max_per_window_reached');
  assert.equal((await reserve(req({ ...u, ...o }), at(61 * M))).allowed, true); // t0 is 61 min old
});

await test('minGap measured from last allowed send; denied attempts do not extend it', async () => {
  const u = { userId: 'gap' }; const o = { minGapMinutes: 90 };
  assert.equal((await reserve(req({ ...u, ...o }), at(0))).allowed, true);
  const d1 = await reserve(req({ ...u, ...o }), at(30 * M));
  assert.equal(d1.reason, 'min_gap_not_elapsed');
  const d2 = await reserve(req({ ...u, ...o }), at(89 * M));
  assert.equal(d2.reason, 'min_gap_not_elapsed');
  assert.equal((await reserve(req({ ...u, ...o }), at(90 * M))).allowed, true);
});

await test('per-call limits are honored (window check uses that call\'s window)', async () => {
  const u = { userId: 'percall' };
  assert.equal((await reserve(req({ ...u, maxPerWindow: 1, windowHours: 2 }), at(0))).allowed, true);
  assert.equal((await reserve(req({ ...u, maxPerWindow: 1, windowHours: 2 }), at(1 * H))).reason, 'max_per_window_reached');
  assert.equal((await reserve(req({ ...u, maxPerWindow: 5, windowHours: 2 }), at(1 * H))).allowed, true);
});

await test('reason distinguishes window vs gap when both apply (window first)', async () => {
  const u = { userId: 'both' };
  assert.equal((await reserve(req({ ...u, maxPerWindow: 1, minGapMinutes: 60 }), at(0))).allowed, true);
  assert.equal((await reserve(req({ ...u, maxPerWindow: 1, minGapMinutes: 60 }), at(5 * M))).reason, 'max_per_window_reached');
});

await test('release frees the slot; double release and unknown ids are no-ops', async () => {
  const u = { userId: 'rel' }; const o = { maxPerWindow: 1 };
  const a = await reserve(req({ ...u, ...o }), at(0));
  assert.equal((await reserve(req({ ...u, ...o }), at(1 * M))).reason, 'max_per_window_reached');
  assert.equal(await release(a.reservationId), true);
  assert.equal(await release(a.reservationId), false);
  assert.equal(await release('not-an-id'), false);
  assert.equal(await release(null), false);
  assert.equal((await reserve(req({ ...u, ...o }), at(2 * M))).allowed, true);
});

await test('released reservation no longer blocks minGap', async () => {
  const u = { userId: 'relgap' }; const o = { minGapMinutes: 90 };
  const a = await reserve(req({ ...u, ...o }), at(0));
  assert.equal((await reserve(req({ ...u, ...o }), at(5 * M))).reason, 'min_gap_not_elapsed');
  await release(a.reservationId);
  assert.equal((await reserve(req({ ...u, ...o }), at(6 * M))).allowed, true);
});

await test('leads are independent', async () => {
  assert.equal((await reserve(req({ userId: 'x1', maxPerWindow: 1 }), at(0))).allowed, true);
  assert.equal((await reserve(req({ userId: 'x2', maxPerWindow: 1 }), at(0))).allowed, true);
});

await test('release from a different process works (history is on disk)', async () => {
  const id = (await reserve(req({ userId: 'proc', maxPerWindow: 1 }), at(0))).reservationId;
  const { stdout } = await exec(process.execPath, ['-e',
    `import('${BOT}').then(async m => console.log(await m.release('${id}')))`], { env: process.env });
  assert.equal(stdout.trim(), 'true');
  assert.equal((await reserve(req({ userId: 'proc', maxPerWindow: 1 }), at(1 * M))).allowed, true);
});

await test('invalid inputs throw', async () => {
  await assert.rejects(reserve(req({ userId: '' }), t0), TypeError);
  await assert.rejects(reserve(req({ maxPerWindow: 0 }), t0), RangeError);
  await assert.rejects(reserve(req({ windowHours: 0 }), t0), RangeError);
  await assert.rejects(reserve(req({ minGapMinutes: -1 }), t0), RangeError);
  await assert.rejects(reserve(req(), '2026-10-22'), TypeError);
  await assert.rejects(reserve(req(), new Date('nope')), TypeError);
});

await test('stale lock from a crashed worker is broken', async () => {
  const key = (await import('node:crypto')).createHash('sha256').update('stale').digest('hex');
  const lock = join(process.env.STATE_DIR, 'leads', `${key}.lock`);
  await mkdir(lock, { recursive: true });
  const old = new Date(Date.now() - 60e3);
  await utimes(lock, old, old);
  const r = await reserve(req({ userId: 'stale' }), at(0));
  assert.equal(r.allowed, true);
});

await test('concurrent workers never exceed maxPerWindow (12 processes x 10 attempts)', async () => {
  const workerPath = '/tmp/bot-test/worker.mjs';
  const nowIso = '2026-10-22T09:00:00Z';
  const runs = await Promise.all(Array.from({ length: 12 }, () =>
    exec(process.execPath, [workerPath, BOT, 'hot_lead', '10', '5', '24', '0', nowIso], { env: process.env })));
  const results = runs.flatMap(r => JSON.parse(r.stdout));
  const allowed = results.filter(r => r.allowed);
  assert.equal(results.length, 120);
  assert.equal(allowed.length, 5);
  assert.equal(new Set(allowed.map(r => r.reservationId)).size, 5);
  assert.ok(results.filter(r => !r.allowed).every(r => r.reason === 'max_per_window_reached' || r.reason === 'limiter_busy'));
});

await test('concurrent workers with minGap: exactly one send in the gap', async () => {
  const runs = await Promise.all(Array.from({ length: 12 }, () =>
    exec(process.execPath, ['/tmp/bot-test/worker.mjs', BOT, 'gap_hot', '3', '100', '24', '90', '2026-10-22T09:00:00Z'], { env: process.env })));
  const allowed = runs.flatMap(r => JSON.parse(r.stdout)).filter(r => r.allowed);
  assert.equal(allowed.length, 1);
});

await test('no temp files left behind in leads dir', async () => {
  const names = await readdir(join(process.env.STATE_DIR, 'leads'));
  assert.ok(names.every(n => !n.endsWith('.tmp') && !n.endsWith('.lock')), names.join(','));
});

console.log(`\n${passed} tests passed. state dir: ${process.env.STATE_DIR}`);
EOF
cd /tmp/bot-test && time node test.mjs
